  if (!g_mainWindow)
    return 1;

  // 4. Standard Win32 Message Loop (Keeps window open, interactive, and responsive)
  MSG msg = {};
  while (GetMessage(&msg, nullptr, 0, 0))
  {
    TranslateMessage(&msg);
    DispatchMessage(&msg);
  }

  return 0;
